INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l44','take part in','',NULL,'/teɪk pɑːrt ɪn/','By the time he is grown, he can take part in its activities.','到他长大时,他就能参与文化的种种活动。','She took part in the debate.','她参加了那场辩论。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l44','hold sway over','',NULL,'/hoʊld sweɪ ˈoʊvər/','Old distinctions held sway over people''s minds.','旧的区分左右着人们的头脑。','Fashion holds sway over the young.','时尚左右着年轻人。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l44','the other way around','',NULL,'/ðə ˈʌðər weɪ əˈraʊnd/','As a matter of fact, it is the other way around.','事实上,恰恰相反。','I thought he was older, but it''s the other way around.','我以为他更大,其实正好反过来。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l44','as a matter of fact','',NULL,'/æz ə ˈmætər ʌv fækt/','As a matter of fact, custom is not commonplace at all.','事实上,习俗根本不是什么平常的东西。','As a matter of fact, I agree with you.','事实上,我同意你。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp1','choice','{"stem":"\"Custom shapes us, ___ how strange an individual''s own actions may be.\"(‘无论多么…’,填引导让步的词组)","options":["in case","even if","as if","no matter"],"answer_index":3,"stem_cn":"无论个人自己的行为多么古怪,习俗都在塑造着我们。","explanation_cn":"‘无论多么…’= no matter how + 形容词;填 no matter。✓ no matter how strange … may be. ✗ even if 即使 / as if 好像 / in case 以防:‘无论多么’用 no matter how。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp1','choice','{"stem":"\"___ how carefully he probes, he cannot escape his own stereotypes.\"(‘无论多么…’,填让步词组)","options":["In case","As if","No matter","Even if"],"answer_index":2,"stem_cn":"无论他探究得多么仔细,都摆脱不了自己的成见。","explanation_cn":"‘无论多么…’用 No matter how。✓ No matter how carefully he probes … ✗ Even if / As if / In case:‘无论多么’用 No matter how。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp1','choice','{"stem":"\"The child absorbs its culture, no matter ___ far away it was born.\"(no matter ___ 结构,填表‘多么’的那个词)","options":["how","which","what","that"],"answer_index":0,"stem_cn":"无论孩子生在多远的地方,都会吸收自己的文化。","explanation_cn":"no matter how + 形容词/副词;填表‘多么’的 how。✓ no matter how far away it was born. ✗ what / which / that:‘无论多么…’用 how。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp2','choice','{"stem":"\"___ the time a child can talk, he is the creature of his culture.\"(‘到…时候’,填引导时间从句的词)","options":["On","By","In","At"],"answer_index":1,"stem_cn":"到孩子会说话时,他已是自己文化的产物。","explanation_cn":"‘到…时候’= By the time;填 By。✓ By the time a child can talk … ✗ At / In / On:‘到…时候’用 By the time。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp2','choice','{"stem":"\"By the time he is grown, its beliefs ___ become his own.\"(by the time + 主句常用完成时,填助动词)","options":["have","do","will","are"],"answer_index":0,"stem_cn":"到他长大时,那些信仰已成了他自己的。","explanation_cn":"by the time 引导时间从句,主句常用完成时;主语 beliefs 复数用 have。✓ its beliefs have become his own. ✗ are / will / do:此处用现在完成 have become。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp2','choice','{"stem":"\"By the time we noticed, the custom ___ already shaped our thinking.\"(by the time + 过去,主句用过去完成,填助动词)","options":["does","will","has","had"],"answer_index":3,"stem_cn":"等我们察觉时,习俗早已塑造了我们的思维。","explanation_cn":"by the time 从句为过去,主句用过去完成;填 had。✓ the custom had already shaped our thinking. ✗ has / will / does:此处用过去完成 had shaped。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp3','choice','{"stem":"\"Any scientific study requires that there ___ no preferential weighting of the items.\"(require that 后从句用动词原形,填 there ___ 里那个原形)","options":["is","be","are","was"],"answer_index":1,"stem_cn":"任何科学研究都要求各项目之间没有偏向性的加权。","explanation_cn":"require that + 从句谓语用(should)动词原形;there be 结构填原形 be。✓ requires that there be no weighting. ✗ is / was / are:虚拟语气用原形 be。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp3','choice','{"stem":"\"The method demands that each variant form ___ noted.\"(demand that 后从句用原形;被动‘___ noted’,填最前那个原形)","options":["was","being","is","be"],"answer_index":3,"stem_cn":"这方法要求每一种变体形式都被记录下来。","explanation_cn":"demand that + 从句用(should)动词原形;被动 be + 过去分词,填原形 be。✓ demands that each form be noted. ✗ is / was / being:虚拟语气用原形 be。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp3','choice','{"stem":"\"He suggested that the researcher ___ set his own belief above others.\"(suggest that + (should) 原形,填‘应当不’里那个否定词)","options":["does not","did not","not","is not"],"answer_index":2,"stem_cn":"他建议研究者不要把自己的信仰凌驾于他人之上。","explanation_cn":"suggest that + (should) 动词原形;否定直接在原形前加 not(should not set)。✓ suggested that the researcher not set … ✗ does not / did not / is not:虚拟否定用 (should) not + 原形。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp4','choice','{"stem":"\"Anthropology was impossible ___ these prejudices held sway over people''s minds.\"(‘只要…’,填引导条件的词组)","options":["as soon as","as well as","as far as","as long as"],"answer_index":3,"stem_cn":"只要这些偏见还左右着人们的头脑,人类学就不可能存在。","explanation_cn":"‘只要…’引导条件用 as long as。✓ as long as these prejudices held sway. ✗ as soon as 一…就 / as well as 以及 / as far as 就…而言:‘只要’用 as long as。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp4','choice','{"stem":"\"We can understand other peoples ___ we stop judging them by our own customs.\"(‘只要…就…’,填条件词组)","options":["as if","as long as","as soon as","as well as"],"answer_index":1,"stem_cn":"只要我们不再用自己的习俗去评判别人,就能理解他们。","explanation_cn":"‘只要…就…’用 as long as。✓ as long as we stop judging them. ✗ as soon as / as well as / as if:‘只要’用 as long as。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp4','choice','{"stem":"\"Custom will rule us ___ we remain ignorant of its laws.\"(‘只要…’,填条件词组)","options":["as much as","as though","as many as","as long as"],"answer_index":3,"stem_cn":"只要我们对习俗的规律一无所知,它就会支配我们。","explanation_cn":"‘只要…’用 as long as。✓ as long as we remain ignorant. ✗ as though / as many as / as much as:‘只要’用 as long as。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp5','choice','{"stem":"\"No one looks at the world freshly; he sees it ___ by his customs.\"(see + 名词 + 过去分词,填‘剪裁/编辑’那个动词的过去分词)","options":["edited","editing","to edit","edit"],"answer_index":0,"stem_cn":"没有人以全新的眼光看世界;他看到的世界已被自己的习俗剪裁过。","explanation_cn":"see + 名词 + 过去分词(表被动完成);填 edit 的过去分词 edited。✓ he sees it edited by his customs. ✗ editing / edit / to edit:此处宾语与动作是被动,用过去分词。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp5','choice','{"stem":"\"We feel the workings of our own minds ___ be worthy of study.\"(feel + 名词 + 不定式,填不定式最前面的记号)","options":["/","of","to","that"],"answer_index":2,"stem_cn":"我们觉得自己头脑的运作值得研究。","explanation_cn":"feel + 名词 + 不定式(feel sth to be…);填不定式记号 to。✓ we feel the workings to be worthy. ✗ 省略 / that / of:feel sth to be 结构用 to。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp5','choice','{"stem":"\"Every community wants its beliefs ___ by the young.\"(want + 名词 + 过去分词,填‘尊重’那个动词的过去分词)","options":["respected","to respect","respect","respecting"],"answer_index":0,"stem_cn":"每个族群都希望自己的信仰被年轻人所尊重。","explanation_cn":"want + 名词 + 过去分词(want sth done);填 respect 的过去分词 respected。✓ wants its beliefs respected. ✗ respecting / respect / to respect:被动完成用过去分词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp6','choice','{"stem":"\"Something ordinary and not at all remarkable is ___.\"(“平凡的,普通的”用哪个词)","options":["commonwealth","commonsense","commonplace","commonly"],"answer_index":2,"stem_cn":"平常、毫不起眼的。","explanation_cn":"平常、毫不起眼的是 commonplace(平凡的、普通的)。✓ ordinary and not remarkable is commonplace. ✗ commonwealth 联邦;✗ commonsense 常识;✗ commonly 通常(副词)——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp6','choice','{"stem":"\"Something of very little importance or value is ___.\"(“琐碎的,微不足道的”用哪个词)","options":["radical","trivial","initial","crucial"],"answer_index":1,"stem_cn":"极不重要或没什么价值的。","explanation_cn":"极不重要或没什么价值的是 trivial(琐碎的、微不足道的)。✓ of very little importance is trivial. ✗ crucial 关键的;✗ radical 激进的;✗ initial 最初的——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',5,'am4_l44_gp6','choice','{"stem":"\"To show or display something clearly is to ___ it.\"(“表明,显示”用哪个词)","options":["manifest","memorize","minimize","magnify"],"answer_index":0,"stem_cn":"清楚地展示或表现某物。","explanation_cn":"清楚地展示或表现某物是 manifest(表明、显示)。✓ to show something clearly is to manifest it. ✗ minimize 使最小化;✗ memorize 记住;✗ magnify 放大——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',6,NULL,'choice','{"stem":"commonplace 的意思是:","options":["珍贵的","罕见的","平凡的,普通的","复杂的"],"answer_index":2,"explanation_cn":"commonplace = 平凡的、普通的。✓ behavior at its most commonplace."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',6,NULL,'choice','{"stem":"aberrant 的意思是:","options":["反常的,越轨的","正常的","温和的","普通的"],"answer_index":0,"explanation_cn":"aberrant = 反常的、越轨的。✓ no matter how aberrant."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',6,NULL,'choice','{"stem":"trivial 的意思是:","options":["重要的","琐碎的,微不足道的","巨大的","严重的"],"answer_index":1,"explanation_cn":"trivial = 琐碎的、微不足道的。✓ only a trivial side of the matter."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',6,NULL,'choice','{"stem":"predominant 的意思是:","options":["隐藏的","微弱的","次要的","占主导地位的,显著的"],"answer_index":3,"explanation_cn":"predominant = 占主导地位的、显著的。✓ the predominant part that custom plays."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',6,NULL,'choice','{"stem":"pristine 的意思是:","options":["崭新的,未受污染的","受损的","陈旧的","肮脏的"],"answer_index":0,"explanation_cn":"pristine = 崭新的、未受污染的。✓ with wholly pristine eyes."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',6,NULL,'choice','{"stem":"stereotype 的意思是:","options":["例外","成见,刻板印象","事实","证据"],"answer_index":1,"explanation_cn":"stereotype = 成见、刻板印象。✓ he cannot get behind these stereotypes."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',7,NULL,'cloze','{"stem":"第 1 空","context":"No matter ___1___ strange his neighbor''s ways may seem, custom shapes us all. ___2___ the time a child can talk, he belongs to his culture. Science demands that no item ___3___ given special weight. Prejudice ruled us ___4___ we kept judging others by our own customs.","blank_no":1,"options":["how","what","which","that"],"answer_index":0,"explanation_cn":"no matter how + 形容词;填 how。✓ No matter how strange his neighbor''s ways may seem …"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',7,NULL,'cloze','{"stem":"第 2 空","context":"No matter ___1___ strange his neighbor''s ways may seem, custom shapes us all. ___2___ the time a child can talk, he belongs to his culture. Science demands that no item ___3___ given special weight. Prejudice ruled us ___4___ we kept judging others by our own customs.","blank_no":2,"options":["By","At","In","On"],"answer_index":0,"explanation_cn":"‘到…时候’= By the time;填 By。✓ By the time a child can talk, he belongs to his culture."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',7,NULL,'cloze','{"stem":"第 3 空","context":"No matter ___1___ strange his neighbor''s ways may seem, custom shapes us all. ___2___ the time a child can talk, he belongs to his culture. Science demands that no item ___3___ given special weight. Prejudice ruled us ___4___ we kept judging others by our own customs.","blank_no":3,"options":["be","is","was","are"],"answer_index":0,"explanation_cn":"require/demand that + 从句用(should)动词原形;填 be。✓ demands that no item be given special weight."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',7,NULL,'cloze','{"stem":"第 4 空","context":"No matter ___1___ strange his neighbor''s ways may seem, custom shapes us all. ___2___ the time a child can talk, he belongs to his culture. Science demands that no item ___3___ given special weight. Prejudice ruled us ___4___ we kept judging others by our own customs.","blank_no":4,"options":["as long as","as soon as","as well as","as far as"],"answer_index":0,"explanation_cn":"‘只要…’引导条件用 as long as。✓ Prejudice ruled us as long as we kept judging others."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',8,NULL,'choice','{"stem":"What shapes a person''s experience and behavior from the very moment of birth?","options":["His own private inventions","The stars he was born under","The customs of the community into which he is born","The books he later reads"],"answer_index":2,"explanation_cn":"录音说:从出生那一刻起,一个人生入的社群习俗就在塑造他的经验与行为。✓ customs of his community."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',8,NULL,'choice','{"stem":"Why does the writer say no one looks at the world with ''pristine eyes''?","options":["Because the world is too complex","Because our eyesight is weak","Because we are born blind to custom","Because we always see it already edited by our customs, institutions and ways of thinking"],"answer_index":3,"explanation_cn":"录音说:没有人用全新的眼睛看世界,我们看到的都是被习俗、制度和思维方式剪裁过的世界。✓ world edited by custom."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',8,NULL,'choice','{"stem":"What did the study of man wrongly do for a long time, according to the passage?","options":["It ignored Western civilization completely","It treated one local variation — Western civilization — as if it were the whole story","It studied only cacti and termites","It refused to group any material"],"answer_index":1,"explanation_cn":"录音说:长久以来,对人的研究把西方文明这一局部变体当成了全部。✓ Western civilization as the whole."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',9,NULL,'choice','{"stem":"你想说\"无论个人的行为多么古怪,习俗都在塑造我们\"(no matter how):","options":["No matter how aberrant an individual''s actions are, but custom shapes us.","No matter what aberrant an individual''s actions are, custom shapes us.","No matter how aberrant an individual''s actions are, custom shapes us.","How aberrant an individual''s actions are, no matter custom shapes us."],"answer_index":2,"explanation_cn":"no matter how + 形容词;主句不再加 but(不写 …, but custom)、how 后接形容词(不用 what)、no matter how 须在句首整体引导。✓ No matter how aberrant …, … 场合:说“无论多么…都…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',9,NULL,'choice','{"stem":"你想说\"到孩子会说话时,他已是自己文化的产物\"(by the time):","options":["By the time a child can talk, he is the creature of his culture.","By a child can talk, he is the creature of his culture.","By the time a child can talk, he was the creature of his culture.","Until the time a child can talk, he is the creature of his culture."],"answer_index":0,"explanation_cn":"by the time 引导时间从句;主句时态一致用 is(不写 was)、不能换 Until(义不同)、不能省 the time(不写 By a child can talk)。✓ By the time …, … 场合:说“到…时候(已经)…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',9,NULL,'choice','{"stem":"你想说\"只要这些偏见还左右着人们的头脑,人类学就不可能存在\"(as long as):","options":["As long as these prejudices held sway over people''s minds, but anthropology was impossible.","As far as these prejudices held sway over people''s minds, anthropology was impossible.","As soon as these prejudices held sway over people''s minds, anthropology was impossible.","As long as these prejudices held sway over people''s minds, anthropology was impossible."],"answer_index":3,"explanation_cn":"as long as 引导条件‘只要’;不用 as soon as(义不同)、主句不再加 but、不用 as far as。✓ As long as …, … 场合:说“只要…(就)…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"commonplace 的意思是:","options":["珍贵的","罕见的","平凡的,普通的","复杂的"],"answer_index":2,"explanation_cn":"commonplace = 平凡的、普通的。✓ behavior at its most commonplace."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"trivial 的意思是:","options":["琐碎的,微不足道的","重要的","严重的","巨大的"],"answer_index":0,"explanation_cn":"trivial = 琐碎的、微不足道的。✓ only a trivial side of the matter."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"\"___ the time a child can talk, he belongs to his culture.\"(‘到…时候’引导时间从句)","options":["In","On","By","At"],"answer_index":2,"stem_cn":"到孩子会说话时,他已属于自己的文化。","explanation_cn":"‘到…时候’= By the time;填 By。✓ By the time a child can talk … ✗ At / In / On。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"\"Science requires that each item ___ treated equally.\"(require that + 从句用动词原形)","options":["be","are","was","is"],"answer_index":0,"stem_cn":"科学要求每一项都被平等对待。","explanation_cn":"require that + 从句用(should)动词原形;填 be。✓ requires that each item be treated equally. ✗ is / was / are。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"\"take part in\" 的意思是:","options":["分开…","反对…","拿走…","参加,参与"],"answer_index":3,"explanation_cn":"take part in = 参加、参与。✓ able to take part in its activities."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"\"hold sway over\" 的意思是:","options":["忽视…","支配,左右","远离…","依赖…"],"answer_index":1,"explanation_cn":"hold sway over = 支配、左右。✓ old distinctions held sway over people''s minds."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"According to the writer, how important is the role of custom in human life?","options":["It plays a predominant role in our experience and belief, far greater than most people assume","It matters only to anthropologists","It affects only primitive peoples","It plays almost no part at all"],"answer_index":0,"passage":"Custom has not usually been thought of as a subject of great importance. The inner workings of our own minds we feel to be uniquely worthy of study, while custom, we tend to think, is behavior at its most commonplace. As a matter of fact, it is the other way around. Traditional custom, taken the world over, is a mass of detailed behavior more astonishing than anything a single person could ever invent on his own, no matter how aberrant. Yet that is only a trivial side of the matter. What is of first-rate importance is the predominant part that custom plays in our experience and belief, and the great variety of forms it may manifest. No one ever looks at the world with wholly pristine eyes. He sees it already edited by a definite set of customs, institutions and ways of thinking. Even in his deepest questioning he cannot get behind these stereotypes; his very notions of the true and the false still refer back to his own particular tradition. A well-known philosopher once said, in all seriousness, that the part played by custom in shaping a person, as against anything he himself can add to that custom, is like the proportion of the whole vocabulary of his mother tongue against the few words of his own baby talk that his family happens to take up. From the moment of his birth, the customs into which a child is born shape his experience and his behavior. By the time he can talk, he is the little creature of his culture; and by the time he is grown and able to take part in its activities, its habits have become his habits, its beliefs his beliefs. Every child born into a given group will come to share them, while no child born on the far side of the globe could ever achieve so much as the thousandth part. There is no social problem it is more incumbent upon us to understand than this role of custom. The study of custom, however, can be profitable only after a few preliminary propositions have been accepted — and some of them have been violently opposed. Any scientific study requires that there be no preferential weighting of one item or another among those it examines. In less controversial fields, the method is simply to gather all the relevant material and to note every possible variant form; it is in this way that we have learned what we know of astronomy or of the social insects. Anthropology was, by its very definition, impossible as long as the old distinctions between ourselves and the barbarian, ourselves and the pagan, held sway over people''s minds. It was necessary first to reach the point where we no longer set our own belief against a neighbor''s superstition, and to recognize that all such institutions must be considered together, our own among the rest.","explanation_cn":"课文说:习俗在我们的经验与信念中起主导作用,远比多数人所以为的大。✓ predominant role of custom."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"What must we accept before the study of custom can be profitable?","options":["That only our own customs are worth studying","That custom cannot be studied scientifically","That no one people''s customs — including our own — should be given special weight over others","That Western civilization is the model for all"],"answer_index":2,"passage":"Custom has not usually been thought of as a subject of great importance. The inner workings of our own minds we feel to be uniquely worthy of study, while custom, we tend to think, is behavior at its most commonplace. As a matter of fact, it is the other way around. Traditional custom, taken the world over, is a mass of detailed behavior more astonishing than anything a single person could ever invent on his own, no matter how aberrant. Yet that is only a trivial side of the matter. What is of first-rate importance is the predominant part that custom plays in our experience and belief, and the great variety of forms it may manifest. No one ever looks at the world with wholly pristine eyes. He sees it already edited by a definite set of customs, institutions and ways of thinking. Even in his deepest questioning he cannot get behind these stereotypes; his very notions of the true and the false still refer back to his own particular tradition. A well-known philosopher once said, in all seriousness, that the part played by custom in shaping a person, as against anything he himself can add to that custom, is like the proportion of the whole vocabulary of his mother tongue against the few words of his own baby talk that his family happens to take up. From the moment of his birth, the customs into which a child is born shape his experience and his behavior. By the time he can talk, he is the little creature of his culture; and by the time he is grown and able to take part in its activities, its habits have become his habits, its beliefs his beliefs. Every child born into a given group will come to share them, while no child born on the far side of the globe could ever achieve so much as the thousandth part. There is no social problem it is more incumbent upon us to understand than this role of custom. The study of custom, however, can be profitable only after a few preliminary propositions have been accepted — and some of them have been violently opposed. Any scientific study requires that there be no preferential weighting of one item or another among those it examines. In less controversial fields, the method is simply to gather all the relevant material and to note every possible variant form; it is in this way that we have learned what we know of astronomy or of the social insects. Anthropology was, by its very definition, impossible as long as the old distinctions between ourselves and the barbarian, ourselves and the pagan, held sway over people''s minds. It was necessary first to reach the point where we no longer set our own belief against a neighbor''s superstition, and to recognize that all such institutions must be considered together, our own among the rest.","explanation_cn":"课文说:研究要有成效,须先接受:任何一族的习俗(包括我们自己的)都不应比别的更受偏重。✓ no preferential weighting."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"By the time a child is grown, whose habits and beliefs does he hold?","options":["Habits he invented by himself","Those of his own culture, which have become entirely his own","The habits of a distant foreign people","No habits or beliefs at all"],"answer_index":1,"audio":"Custom has not usually been thought of as a subject of great importance. The inner workings of our own minds we feel to be uniquely worthy of study, while custom, we tend to think, is behavior at its most commonplace. As a matter of fact, it is the other way around. Traditional custom, taken the world over, is a mass of detailed behavior more astonishing than anything a single person could ever invent on his own, no matter how aberrant. Yet that is only a trivial side of the matter. What is of first-rate importance is the predominant part that custom plays in our experience and belief, and the great variety of forms it may manifest. No one ever looks at the world with wholly pristine eyes. He sees it already edited by a definite set of customs, institutions and ways of thinking. Even in his deepest questioning he cannot get behind these stereotypes; his very notions of the true and the false still refer back to his own particular tradition. A well-known philosopher once said, in all seriousness, that the part played by custom in shaping a person, as against anything he himself can add to that custom, is like the proportion of the whole vocabulary of his mother tongue against the few words of his own baby talk that his family happens to take up. From the moment of his birth, the customs into which a child is born shape his experience and his behavior. By the time he can talk, he is the little creature of his culture; and by the time he is grown and able to take part in its activities, its habits have become his habits, its beliefs his beliefs. Every child born into a given group will come to share them, while no child born on the far side of the globe could ever achieve so much as the thousandth part. There is no social problem it is more incumbent upon us to understand than this role of custom. The study of custom, however, can be profitable only after a few preliminary propositions have been accepted — and some of them have been violently opposed. Any scientific study requires that there be no preferential weighting of one item or another among those it examines. In less controversial fields, the method is simply to gather all the relevant material and to note every possible variant form; it is in this way that we have learned what we know of astronomy or of the social insects. Anthropology was, by its very definition, impossible as long as the old distinctions between ourselves and the barbarian, ourselves and the pagan, held sway over people''s minds. It was necessary first to reach the point where we no longer set our own belief against a neighbor''s superstition, and to recognize that all such institutions must be considered together, our own among the rest.","explanation_cn":"课文说:到孩子长大时,文化的习惯与信念已彻底成了他自己的。✓ culture''s habits become his own."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l44',10,NULL,'choice','{"stem":"What made anthropology possible at last?","options":["Setting our beliefs against others'' superstitions","Abandoning the study of custom","Recognizing that our own institutions must be studied together with all others, on the same terms","Proving Western customs were best"],"answer_index":2,"audio":"Custom has not usually been thought of as a subject of great importance. The inner workings of our own minds we feel to be uniquely worthy of study, while custom, we tend to think, is behavior at its most commonplace. As a matter of fact, it is the other way around. Traditional custom, taken the world over, is a mass of detailed behavior more astonishing than anything a single person could ever invent on his own, no matter how aberrant. Yet that is only a trivial side of the matter. What is of first-rate importance is the predominant part that custom plays in our experience and belief, and the great variety of forms it may manifest. No one ever looks at the world with wholly pristine eyes. He sees it already edited by a definite set of customs, institutions and ways of thinking. Even in his deepest questioning he cannot get behind these stereotypes; his very notions of the true and the false still refer back to his own particular tradition. A well-known philosopher once said, in all seriousness, that the part played by custom in shaping a person, as against anything he himself can add to that custom, is like the proportion of the whole vocabulary of his mother tongue against the few words of his own baby talk that his family happens to take up. From the moment of his birth, the customs into which a child is born shape his experience and his behavior. By the time he can talk, he is the little creature of his culture; and by the time he is grown and able to take part in its activities, its habits have become his habits, its beliefs his beliefs. Every child born into a given group will come to share them, while no child born on the far side of the globe could ever achieve so much as the thousandth part. There is no social problem it is more incumbent upon us to understand than this role of custom. The study of custom, however, can be profitable only after a few preliminary propositions have been accepted — and some of them have been violently opposed. Any scientific study requires that there be no preferential weighting of one item or another among those it examines. In less controversial fields, the method is simply to gather all the relevant material and to note every possible variant form; it is in this way that we have learned what we know of astronomy or of the social insects. Anthropology was, by its very definition, impossible as long as the old distinctions between ourselves and the barbarian, ourselves and the pagan, held sway over people''s minds. It was necessary first to reach the point where we no longer set our own belief against a neighbor''s superstition, and to recognize that all such institutions must be considered together, our own among the rest.","explanation_cn":"课文说:人类学之所以终于可能,在于认清我们自己的制度必须与所有别的制度放在一起、以同样的标准来研究。✓ study all institutions together."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l45',4,8,45,'Of Men and Galaxies','人与星系','not so much A as B(与其说A不如说B)、与过去事实相反的虚拟(would have done)、must have done(对过去的肯定推测)、such … that(如此…以致)、过去分词作后置定语(the process envisioned / pages handed)(NCE4 该课源无独立 KS 页,考点由课文结构自取;IP:源为 Fred Hoyle《Of Men and Galaxies》一段论‘观念比武器更能塑造人的环境’的科普随笔,系版权作品——已用 100% 原创行文复述其观点、无引用原句;⚠️净化:原文‘焚烧异端’改为‘噤声压制’、‘核弹造法’淡化为‘一种危险技术举例’、殖民框架中性化;题材=思想史/科普·净化后无害;美语化 analyze/organize;第四册第45课)','在人类的早年,他与别的生物之间的竞争一定曾是生死攸关的。可我们发展的那个阶段早已结束。的确,如今我们全然没了应付原始环境的历练;若没有现代工具,我十分确信,自己去和一头熊争夺一个山洞的归属,会表现得非常糟糕——而且我想,这一点上我并不孤单。最后一个认真与人相争的生物是蚊子;而就连蚊子,也已因排水的整治与化学喷剂而大体被制服。然而,我们彼此之间的竞争——人对人、群体对群体——依旧存在,而且和从前一样激烈。可人与人之间的竞争,并不是生物学里所设想的那种简单过程。它不是为一份由物质世界所固定的、定量食物而进行的单纯争夺,因为如今塑造我们发展的环境,已不再本质上是物质性的。我们的环境,主要由我们所相信的东西所决定。摩洛哥与加利福尼亚是地球上纬度十分相近的两块地方,都在大陆的西海岸,气候相似,天然资源大概也相当接近;然而二者如今的发展却截然不同——与其说是因为土地有何差异,不如说是因为住在那里的人心中所想有别。我们环境中最重要的因素,是我们自己心智的状态。众所周知,当一种文化遇上另一种文化时,最具破坏力的影响,往往不是来自武器,而是来自观念。观念可能是危险的。早年间一个强大的权威深知这一点:它惧怕某些信念,便把持有这些信念的人打成异端,竭尽全力去将其噤声。的确,言论自由这一概念之所以能在一个社会里生长,正是因为当你身处一个群体之内时,你被它的种种成规塑造到如此程度,以致你很难构想出任何真正具有破坏力的东西。往往是一个从外面旁观的人,才能注入那危险的念头。我毫不怀疑,把某些观念引入现代世界、足以将它彻底改造,是完全可能的。也许只需想一想一种危险的技术,比如核弹:一份几页长的资料,若在1925年前后交到任何一个主要大国手里,很可能就足以改变整个世界历史的走向。这是个奇怪的念头,但我相信它是对的:二三十页的观念,就能把当今的世界搅个天翻地覆,甚至将其摧毁。在我们大脑被塑造成的那些特定模式之外,我们只能想出极其有限的一点点——而且惟有当我们极富原创性时才能做到。','{"q":"Listen and answer — What is the most influential factor in any human society?","options":["The state of our own minds — the things we believe","The amount of food available","The climate and natural resources","The weapons a society owns"],"answer_index":0}'::jsonb,'{"title":"not so much A as B / 与过去相反的虚拟 would have done / must have done / such … that / 过去分词作后置定语","intro":"①not so much A as B:‘与其说A不如说B’。②与过去事实相反的虚拟:主句用 would/could/might + have + 过去分词。③must have done:对过去的肯定推测,‘一定曾…’。④such + (a) + 名词 + that:‘如此…以致…’。⑤过去分词作后置定语:名词 + 过去分词短语,表被动完成(the process envisioned in biology)。","table":{"headers":["用法","结构","例子"],"rows":[["not so much A as B","not so much A as B","not so much land as minds"],["与过去相反的虚拟","would/could + have + 过去分词","would have changed history"],["must have done","must + have + 过去分词","competition must have been critical"],["such … that","such + (a) + 名词 + that","such a degree that …"],["过去分词作后置定语","名词 + 过去分词短语","the process envisioned in biology"]]},"specialRules":[{"rule":"对过去的推测:must have done(肯定)/ may(might) have done(可能)/ can''t have done(否定)。","mark":"must have done"},{"rule":"such 后接名词(such a degree、such power);so 后接形容词/副词(so great)。二者都可接 that 从句。","mark":"such + 名词 + that"},{"rule":"美式拼写:analyze(分析,英式 analyse)、organize(组织,英式 organise)。本课已按美语写。","mark":"analyze / organize"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l45',1,NULL,'In man''s early days, his competition with other creatures must have been a matter of life and death. But that phase of our development is long over. Indeed, we now lack all practice in dealing with primitive conditions; without modern tools, I am quite sure I would make a very poor show of disputing the ownership of a cave with a bear, and in this I do not think I stand alone. The last creature to compete seriously with man was the mosquito — and even the mosquito has been largely subdued by attention to drainage and by chemical sprays.','在人类的早年,他与别的生物之间的竞争一定曾是生死攸关的。可我们发展的那个阶段早已结束。的确,如今我们全然没了应付原始环境的历练;若没有现代工具,我十分确信,自己去和一头熊争夺一个山洞的归属,会表现得非常糟糕——而且我想,这一点上我并不孤单。最后一个认真与人相争的生物是蚊子;而就连蚊子,也已因排水的整治与化学喷剂而大体被制服。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l45',2,NULL,'Competition among ourselves, person against person and community against community, still persists, however, and it is as fierce as it ever was. Yet the competition of man against man is not the simple process envisioned in biology. It is not a plain struggle for a fixed amount of food fixed by the physical world, because the environment that now shapes our development is no longer essentially physical. Our environment is chiefly conditioned by the things we believe.','然而,我们彼此之间的竞争——人对人、群体对群体——依旧存在,而且和从前一样激烈。可人与人之间的竞争,并不是生物学里所设想的那种简单过程。它不是为一份由物质世界所固定的、定量食物而进行的单纯争夺,因为如今塑造我们发展的环境,已不再本质上是物质性的。我们的环境,主要由我们所相信的东西所决定。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l45',3,NULL,'Morocco and California are patches of the Earth at very similar latitudes, both on the west coasts of continents, with similar climates and probably rather similar natural resources; yet their present development is wholly different — not so much because of any difference in the land as because of a difference in the minds of the people who live there. The most important factor in our environment is the state of our own minds.','摩洛哥与加利福尼亚是地球上纬度十分相近的两块地方,都在大陆的西海岸,气候相似,天然资源大概也相当接近;然而二者如今的发展却截然不同——与其说是因为土地有何差异,不如说是因为住在那里的人心中所想有别。我们环境中最重要的因素,是我们自己心智的状态。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l45',4,NULL,'It is well known that where one culture has met another, the most destructive effects have often come not from physical weapons but from ideas. Ideas can be dangerous. A powerful authority of earlier ages understood this well: fearing certain beliefs, it branded those who held them heretics and did all it could to silence them. Indeed, the very concept of free speech can flourish in a society only because, when you are inside a community, you are conditioned by its conventions to such a degree that it is very difficult to conceive of anything truly destructive.','众所周知,当一种文化遇上另一种文化时,最具破坏力的影响,往往不是来自武器,而是来自观念。观念可能是危险的。早年间一个强大的权威深知这一点:它惧怕某些信念,便把持有这些信念的人打成异端,竭尽全力去将其噤声。的确,言论自由这一概念之所以能在一个社会里生长,正是因为当你身处一个群体之内时,你被它的种种成规塑造到如此程度,以致你很难构想出任何真正具有破坏力的东西。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l45',5,NULL,'It is usually someone looking on from outside who can inject the dangerous thought. I do not doubt that it would be possible to introduce into the modern world ideas that could utterly transform it. A few pages of information, handed to any of the major world powers around the year 1925, might well have been enough to change the whole course of world history. Outside the particular patterns to which our brains are conditioned, we can think only a very little way — and then only if we are very original.','往往是一个从外面旁观的人,才能注入那危险的念头。我毫不怀疑,把某些观念引入现代世界、足以将它彻底改造,是完全可能的。一份几页长的资料,若在1925年前后交到任何一个主要大国手里,很可能就足以改变整个世界历史的走向。在我们大脑被塑造成的那些特定模式之外,我们只能想出极其有限的一点点——而且惟有当我们极富原创性时才能做到。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
