INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l47','get away from it all','',NULL,'/ɡet əˈweɪ frʌm ɪt ɔːl/','The traveler had sworn to get away from it all.','那旅行者发誓要彻底摆脱一切。','We went to the mountains to get away from it all.','我们去山里,为的是彻底放空自己。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l47','at hand','',NULL,'/æt hænd/','From door to hills and back, everything is at hand.','从门口到山间再回来,一切都近在手边。','Help was at hand when we needed it.','我们需要时,帮助就在近旁。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l47','door to door','',NULL,'/dɔːr tə dɔːr/','A small car stands door to door with a grander one.','一辆小车与一辆更气派的车门挨着门。','They carried the boxes door to door.','他们挨家挨户地搬运箱子。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l47','not least','',NULL,'/nɑːt liːst/','Car worship is explained, not least, by a sense of freedom.','对汽车的崇拜,尤其可用一种自由感来解释。','Many people came, not least the neighbors.','许多人来了,尤其是邻居们。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp1','choice','{"stem":"\"___ only are the means of arriving within one''s keeping, but escape is easy too.\"(‘不但…而且…’置于句首、后接部分倒装,填句首那个否定副词)","options":["None","Nor","No","Not"],"answer_index":3,"stem_cn":"到达的手段不但在自己掌握之中,逃离也很容易。","explanation_cn":"‘不但…而且…’置于句首用 Not only;填句首的否定副词 Not。✓ Not only are the means within one''s keeping, but escape is easy. ✗ No / Nor / None:与 only 搭配、领起倒装的是 Not。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp1','choice','{"stem":"\"Not only ___ the car a means of arrival, but also a means of escape.\"(Not only 置于句首,主句部分倒装,把 be 动词提到主语前,填提前的那个 be 动词)","options":["is","it is","does","being"],"answer_index":0,"stem_cn":"汽车不但是到达的工具,也是逃离的工具。","explanation_cn":"Not only 置于句首,主句要部分倒装,把 be 动词提到主语 the car 前;填 is。✓ Not only is the car a means of arrival… ✗ it is(未倒装)/ does(此处是 be 动词句)/ being:倒装后 be 动词提前用 is。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp1','choice','{"stem":"\"The site drew not only Germans ___ also the Dutch and the French.\"(not only … ___ also …,填与 not only 呼应的那个词)","options":["so","or","and","but"],"answer_index":3,"stem_cn":"这处营地不但吸引德国人,也吸引荷兰人和法国人。","explanation_cn":"not only … but (also) … 关联结构;与 not only 呼应的是 but。✓ not only Germans but also the Dutch. ✗ and / or / so:与 not only 搭配的是 but。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp2','choice','{"stem":"\"___ organized camping will kill the freer kind is hard to say.\"(‘是否…’引导主语从句置于句首,填那个引导词)","options":["If","Whether","That","What"],"answer_index":1,"stem_cn":"有组织的露营是否会杀死更自由的那种,很难说。","explanation_cn":"‘是否…’引导主语从句、置于句首作主语,只能用 Whether;if 不能引导主语从句。✓ Whether it will kill the freer kind is hard to say. ✗ If(不能引导主语从句)/ That(不表‘是否’)/ What。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp2','choice','{"stem":"\"___ the beach is too crowded or not, the car is ready to leave.\"(‘无论…是否…’,与 or not 搭配的引导词)","options":["Whether","That","If","Which"],"answer_index":0,"stem_cn":"无论海滩挤不挤,汽车都随时可以开走。","explanation_cn":"与 or not 搭配、表‘无论…是否…’,只能用 Whether;if 一般不与 or not 连用于句首。✓ Whether the beach is crowded or not… ✗ If / That / Which。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp2','choice','{"stem":"\"It is hard to say ___ the growth is a good thing or a bad one.\"(动词 say 后接‘是…还是…’,与 or 搭配的引导词)","options":["what","whether","how","that"],"answer_index":1,"stem_cn":"很难说这种发展是好事还是坏事。","explanation_cn":"say 后接‘是…还是…’,与 or 搭配表选择,用 whether。✓ hard to say whether it is good or bad. ✗ that(不表选择)/ what / how。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp3','choice','{"stem":"\"Steering in carelessly, he may find ___ parked beside a luxury car.\"(find + 反身代词 + 分词,填与主语 he 一致的反身代词)","options":["himself","him","he","his"],"answer_index":0,"stem_cn":"漫不经心地开进去,他可能发现自己正停在一辆豪车旁边。","explanation_cn":"find + 反身代词 + 分词;主语是 he,反身代词用 himself。✓ he may find himself parked beside a car. ✗ him(宾格非反身)/ his(所有格)/ he(主格):此处要反身代词。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp3','choice','{"stem":"\"You may find yourself ___ door to door with a stranger''s tent.\"(find oneself + 现在分词,填 stand 的 -ing 形式)","options":["stood","to stand","stand","standing"],"answer_index":3,"stem_cn":"你可能发现自己与陌生人的帐篷门挨着门。","explanation_cn":"find oneself + 现在分词,表‘发现自己正在…’;填 stand 的 -ing 形式 standing。✓ find yourself standing door to door. ✗ stand / stood / to stand:find oneself 后用现在分词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp3','choice','{"stem":"\"They found themselves ___ a site with campers from six countries.\"(find oneself + 现在分词,填 share 的 -ing 形式)","options":["sharing","to share","share","shared"],"answer_index":0,"stem_cn":"他们发现自己与来自六个国家的露营者共用一处营地。","explanation_cn":"find oneself + 现在分词;填 share 的 -ing 形式 sharing。✓ found themselves sharing a site. ✗ share / shared / to share:find oneself 后用现在分词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp4','choice','{"stem":"\"Thrift is far ___ being the only motive for camping.\"(‘远非…’的固定说法 far ___ + 动名词,填 far 与动名词之间那个介词)","options":["of","off","from","than"],"answer_index":2,"stem_cn":"省钱远不是露营唯一的动机。","explanation_cn":"‘远非…’= far from + 动名词;far 之后接介词 from。✓ far from being the only motive. ✗ of / than / off:此结构是 far from doing。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp4','choice','{"stem":"\"The total cost can be far ___ than a run of hotel bills.\"(‘远比…少’= far + 比较级 + than,填 little 的比较级)","options":["least","less","lesser","little"],"answer_index":1,"stem_cn":"总花费可能远远少于一连串的旅馆账单。","explanation_cn":"‘远比…少’= far + 比较级 + than;little 的比较级是 less。✓ far less than a run of hotel bills. ✗ little(原级)/ least(最高级)/ lesser(用于抽象‘次要的’):比较 than 用 less。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp4','choice','{"stem":"\"Camping is far from ___ as dull as its critics claim.\"(‘远非…’= far from + 动名词;形容词短语前要加 be 的动名词形式,填该词)","options":["been","be","being","to be"],"answer_index":2,"stem_cn":"露营远不像批评者所说的那样乏味。","explanation_cn":"far from 后接动名词;形容词短语前加 being;填 be 的动名词 being。✓ far from being as dull as critics claim. ✗ be / been / to be:far from 后用动名词 being。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp5','choice','{"stem":"\"Notices ___ the drying of clothes are printed in three languages.\"(现在分词作后置定语,表主动‘禁止…的告示’,填 forbid 的 -ing 形式)","options":["forbid","forbidding","forbidden","to forbid"],"answer_index":1,"stem_cn":"禁止晾晒衣服的告示用三种语言印出。","explanation_cn":"现在分词作后置定语,表主动‘禁止…的告示’(= notices that forbid);填 forbid 的 -ing 形式 forbidding。✓ notices forbidding the drying of clothes. ✗ forbidden(过去分词表被动,意思变‘被禁止的告示’)/ forbid / to forbid。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp5','choice','{"stem":"\"Signs ___ campers to a dance hang by the gate.\"(现在分词作后置定语‘邀请…的告示’,填 invite 的 -ing 形式)","options":["to invite","invite","inviting","invited"],"answer_index":2,"stem_cn":"邀请露营者去跳舞的告示挂在门边。","explanation_cn":"现在分词作后置定语,‘邀请…的告示’;填 invite 的 -ing 形式 inviting。✓ signs inviting campers to a dance. ✗ invited(被动)/ invite / to invite:主动的后置定语用现在分词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp5','choice','{"stem":"\"A traveler ___ to get away from it all chooses a tent.\"(现在分词作后置定语修饰 traveler,填 hope 的 -ing 形式)","options":["hope","hoping","to hope","hoped"],"answer_index":1,"stem_cn":"一个渴望彻底摆脱一切的旅行者选择了帐篷。","explanation_cn":"现在分词作后置定语修饰 traveler,‘渴望…的旅行者’;填 hope 的 -ing 形式 hoping。✓ a traveler hoping to get away from it all. ✗ hoped / hope / to hope:主动的后置定语用现在分词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp6','choice','{"stem":"\"A widely held belief that is taken for granted is an ___.\"(“假定,假设”用哪个词)","options":["assumption","assortment","assignment","assessment"],"answer_index":0,"stem_cn":"一种被想当然接受的普遍看法。","explanation_cn":"被想当然接受的普遍看法是 assumption(假定、假设)。✓ contrary to a common assumption. ✗ assignment 任务;✗ assortment 各式各样;✗ assessment 评估——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp6','choice','{"stem":"\"A person who deliberately keeps away from something is said to ___ it.\"(“避开,回避”用哪个词)","options":["shine","shrink","shift","shun"],"answer_index":3,"stem_cn":"故意远离某物。","explanation_cn":"故意远离某物是 shun(避开、回避)。✓ he wishes to shun them. ✗ shine 发光;✗ shift 转移;✗ shrink 收缩——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',5,'am4_l47_gp6','choice','{"stem":"\"To make people feel distant and unfriendly toward you is to ___ them.\"(“使疏远,离间”用哪个词)","options":["allocate","alternate","alienate","alleviate"],"answer_index":2,"stem_cn":"使人对你感到疏远和不友好。","explanation_cn":"使人对你感到疏远、不友好是 alienate(使疏远、离间)。✓ whether they alienate the countryside. ✗ alleviate 减轻;✗ allocate 分配;✗ alternate 交替——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',6,NULL,'choice','{"stem":"assumption 的意思是:","options":["假定,假设","结论","事实","证据"],"answer_index":0,"explanation_cn":"assumption = 假定、假设。✓ contrary to a common assumption."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',6,NULL,'choice','{"stem":"paradox 的意思是:","options":["简单的问题","悖论,自相矛盾的事","常见的错误","显而易见的真理"],"answer_index":1,"explanation_cn":"paradox = 悖论、自相矛盾的事。✓ an amusing paradox for the cynic."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',6,NULL,'choice','{"stem":"cynic 的意思是:","options":["专家","乐观主义者","梦想家","愤世嫉俗者"],"answer_index":3,"explanation_cn":"cynic = 愤世嫉俗者。✓ a paradox for the cynic."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',6,NULL,'choice','{"stem":"affluent 的意思是:","options":["慷慨的","贫穷的","富裕的","吝啬的"],"answer_index":2,"explanation_cn":"affluent = 富裕的。✓ affluent he may be."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',6,NULL,'choice','{"stem":"cater 的意思是:","options":["迎合,满足需求","忽视,无视","拒绝,回绝","批评,指责"],"answer_index":0,"explanation_cn":"cater = 迎合、满足需求。✓ hotels tend to cater to one nationality."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',6,NULL,'choice','{"stem":"cosmopolitan 的意思是:","options":["古老的,过时的","世界性的,国际化的","本地的,地方性的","私人的,隐秘的"],"answer_index":1,"explanation_cn":"cosmopolitan = 世界性的、国际化的。✓ campsites are strongly cosmopolitan."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',7,NULL,'cloze','{"stem":"第 1 空","context":"Thrift is far ___1___ being the only reason for camping. The car matters too: not only ___2___ it a way of arriving, but also a way of escape. Notices ___3___ the drying of clothes are printed in many languages, for the sites are strongly ___4___.","blank_no":1,"options":["from","of","than","off"],"answer_index":0,"explanation_cn":"‘远非…’= far from + 动名词;填 from。✓ far from being the only reason."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',7,NULL,'cloze','{"stem":"第 2 空","context":"Thrift is far ___1___ being the only reason for camping. The car matters too: not only ___2___ it a way of arriving, but also a way of escape. Notices ___3___ the drying of clothes are printed in many languages, for the sites are strongly ___4___.","blank_no":2,"options":["is","it is","does","being"],"answer_index":0,"explanation_cn":"Not only 置于句首要部分倒装,be 动词提到主语前;填 is。✓ not only is it a way of arriving."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',7,NULL,'cloze','{"stem":"第 3 空","context":"Thrift is far ___1___ being the only reason for camping. The car matters too: not only ___2___ it a way of arriving, but also a way of escape. Notices ___3___ the drying of clothes are printed in many languages, for the sites are strongly ___4___.","blank_no":3,"options":["forbidding","forbidden","forbid","to forbid"],"answer_index":0,"explanation_cn":"现在分词作后置定语,‘禁止…的告示’;填 forbidding。✓ notices forbidding the drying of clothes."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',7,NULL,'cloze','{"stem":"第 4 空","context":"Thrift is far ___1___ being the only reason for camping. The car matters too: not only ___2___ it a way of arriving, but also a way of escape. Notices ___3___ the drying of clothes are printed in many languages, for the sites are strongly ___4___.","blank_no":4,"options":["cosmopolitan","private","empty","local"],"answer_index":0,"explanation_cn":"营地接纳各国旅客,是高度‘国际化的’;填 cosmopolitan。✓ the sites are strongly cosmopolitan."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',8,NULL,'choice','{"stem":"What does the writer say about the cost of camping compared with hotels?","options":["Camping and hotels cost exactly the same","Camping always costs more than a good hotel","The cost of camping cannot be worked out at all","Once the gear is paid for or rented, the total cost can be far less than a run of hotel bills"],"answer_index":3,"explanation_cn":"录音说:装备付清或租好后,露营总花费可远少于一连串旅馆账单。✓ far less than hotel bills."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',8,NULL,'choice','{"stem":"According to the writer, why does the modern traveler often dislike the grand hotel?","options":["Because he is not allowed to bring a car","Because the food there is always bad","Not because he cannot afford it, but because he is a little afraid of it — unsure what to tip or when to complain","Because hotels are never near the sea"],"answer_index":2,"explanation_cn":"录音说:现代旅行者讨厌高级旅馆不是因为付不起,而是有点怕它——拿不准给多少小费、何时抱怨。✓ afraid of the hotel."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',8,NULL,'choice','{"stem":"Where nationality is concerned, how do campsites differ from holiday hotels?","options":["Hotels are more international than campsites","Campsites are strongly cosmopolitan, while hotels tend to cater to one nationality","There is no difference at all between them","Campsites admit only one nationality at a time"],"answer_index":1,"explanation_cn":"录音说:露营地高度国际化,而旅馆往往只迎合一个国籍的客人。✓ campsites cosmopolitan."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',9,NULL,'choice','{"stem":"你想说\"省钱远不是露营唯一的原因\"(far from doing):","options":["Saving money is far away being the only reason for camping.","Saving money is far being the only reason for camping.","Saving money is far from being the only reason for camping.","Saving money is far from be the only reason for camping."],"answer_index":2,"explanation_cn":"‘远非…’要用 far from + 动名词(being),不能漏 from、也不能把 from 后的动词写成原形(be)或写成 far away。✓ far from being the only reason. 场合:说“远不是…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',9,NULL,'choice','{"stem":"你想说\"不但汽车是到达的工具,它也是逃离的工具\"(Not only 置句首的部分倒装):","options":["Not only the car a means of arriving, but it is also a means of escape.","Not only is the car a means of arriving, but it is also a means of escape.","Not only the car is a means of arriving, but it is also a means of escape.","Not only is the car a means of arriving, but also it is a means of escape."],"answer_index":1,"explanation_cn":"Not only 放句首,后面主句要倒装(is the car,而非 the car is);后半句 also 放在 it is 之后(but it is also),不写 but also it is。✓ Not only is the car…, but it is also… 场合:说“不但…而且…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',9,NULL,'choice','{"stem":"你想说\"有组织的露营是否会杀死更自由的那种,很难说\"(whether 引导主语从句):","options":["Whether organized camping will kill the freer kind is hard to say.","If organized camping will kill the freer kind is hard to say.","Whether organized camping will kill the freer kind are hard to say.","That organized camping will kill the freer kind is hard to say whether."],"answer_index":0,"explanation_cn":"开头用 Whether 表示‘是否’(这里不能用 If);中间的 is 用单数;Whether 放在句子开头,不能挪到最后。✓ Whether … is hard to say. 场合:说“……是否……,很难说”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',10,NULL,'choice','{"stem":"affluent 的意思是:","options":["富裕的","慷慨的","孤独的","贫穷的"],"answer_index":0,"explanation_cn":"affluent = 富裕的。✓ affluent he may be."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',10,NULL,'choice','{"stem":"shun 的意思是:","options":["接受,认可","面对,直面","追求,寻求","避开,回避"],"answer_index":3,"explanation_cn":"shun = 避开、回避。✓ he wishes to shun them."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',10,NULL,'choice','{"stem":"\"Not only ___ the car a means of arrival, but also a means of escape.\"(Not only 置句首的部分倒装)","options":["being","is","it is","does"],"answer_index":1,"stem_cn":"汽车不但是到达的工具,也是逃离的工具。","explanation_cn":"Not only 置于句首要部分倒装,be 动词提到主语 the car 前;填 is。✓ Not only is the car a means of arrival. ✗ it is(未倒装)/ does / being。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',10,NULL,'choice','{"stem":"\"Thrift is far ___ being the only motive for camping.\"(‘远非…’,far 之后接介词)","options":["from","off","than","of"],"answer_index":0,"stem_cn":"省钱远不是露营唯一的动机。","explanation_cn":"‘远非…’= far from + 动名词;far 之后接介词 from。✓ far from being the only motive. ✗ of / than / off。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',10,NULL,'choice','{"stem":"\"get away from it all\" 的意思是:","options":["把一切都搬走","放弃所有计划","彻底摆脱日常烦扰","把东西分给大家"],"answer_index":2,"explanation_cn":"get away from it all = 彻底摆脱日常烦扰。✓ sworn to get away from it all."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',10,NULL,'choice','{"stem":"\"cater to\" 的意思是:","options":["打扫卫生","拒绝招待","收取费用","迎合,满足(某类人的)需求"],"answer_index":3,"explanation_cn":"cater to = 迎合、满足某类人的需求。✓ hotels cater to one nationality."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',10,NULL,'choice','{"stem":"According to the writer, why does camping set the modern traveler free from certain fears?","options":["Because tents are more comfortable than rooms","Because campsites forbid all foreigners","Because there is no management or hotel hierarchy, and no superior ''they'', to darken his holiday","Because camping is always cheaper than a hotel"],"answer_index":2,"passage":"Saving money is one powerful reason for camping. Once you have paid for your gear, or arranged to rent it, the total cost can be far less than a run of hotel bills. But, contrary to a common assumption, thrift is far from being the only reason, or even the greatest. The traveler who steers carelessly into his small paid square at one of Europe''s countless permanent sites may well find himself parked beside a gleaming sedan; more often a modest hatchback stands door to door with something far grander. That the gear of modern camping grows more elaborate every year is an amusing paradox for the cynic, and a brighter promise for the hopeful traveler who has sworn to get away from it all. It also offers — and some student of sociology might build a thesis on the fact — an escape of a different kind. The modern traveler is often a man who dislikes the grand hotel, not because he cannot afford its comforts or wishes to shun them, but because he is a little afraid of it. Affluent he may be, yet he is by no means sure what to tip the doorman or the maid. Master in his own house, he has small idea of when to complain to a headwaiter. From all such fears camping sets him free. A snobbery of camping does exist, based on gear and technique; but it is a kind that, should he meet it, he can readily understand and handle. There is no superior ''they'', no management and no hotel hierarchy, to darken his holiday. To these motives another must be added. The modern worship of the car is explained, not least, by the sense of independence that ownership entails. To this pleasure, camping gives a fine refinement. From one''s own front door to the hills or the sands and home again, everything is at hand. Not only are the means of reaching the holiday paradise within one''s own keeping, but the means of escaping a holiday that has soured — a beach too crowded, a sky too gray — are parked outside the tent, or are part of it. Idealists object that the camper, like the package tourist, denies himself the chance of getting to know the country he visits. Yet the charge does not survive a visit to a busy Continental site. Holiday hotels tend to cater to one nationality, sometimes to one alone; campsites, by contrast, are strongly cosmopolitan. Notices forbidding the drying of clothes in the open, or inviting ''our camping friends'' to a dance, are printed in French, German, and English alike. Whether the remarkable growth of organized camping means the slow death of the freer, more independent kind is hard to say. In the end it will depend on the campers themselves — on how many fires they start, how much litter they leave, and whether they wholly alienate the people of the countryside.","explanation_cn":"课文说:露营让旅行者免于种种担忧,因为没有管理层、没有旅馆等级、没有高人一等的‘他们’来给假日蒙阴影。✓ no hierarchy."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',10,NULL,'choice','{"stem":"What does a busy Continental campsite show about the idealists'' objection to camping?","options":["That hotels are friendlier than campsites","The charge that campers never meet the locals does not survive such a visit, for the sites are strongly cosmopolitan","That campsites are always empty in summer","That campers really do stay among their own nationality"],"answer_index":1,"passage":"Saving money is one powerful reason for camping. Once you have paid for your gear, or arranged to rent it, the total cost can be far less than a run of hotel bills. But, contrary to a common assumption, thrift is far from being the only reason, or even the greatest. The traveler who steers carelessly into his small paid square at one of Europe''s countless permanent sites may well find himself parked beside a gleaming sedan; more often a modest hatchback stands door to door with something far grander. That the gear of modern camping grows more elaborate every year is an amusing paradox for the cynic, and a brighter promise for the hopeful traveler who has sworn to get away from it all. It also offers — and some student of sociology might build a thesis on the fact — an escape of a different kind. The modern traveler is often a man who dislikes the grand hotel, not because he cannot afford its comforts or wishes to shun them, but because he is a little afraid of it. Affluent he may be, yet he is by no means sure what to tip the doorman or the maid. Master in his own house, he has small idea of when to complain to a headwaiter. From all such fears camping sets him free. A snobbery of camping does exist, based on gear and technique; but it is a kind that, should he meet it, he can readily understand and handle. There is no superior ''they'', no management and no hotel hierarchy, to darken his holiday. To these motives another must be added. The modern worship of the car is explained, not least, by the sense of independence that ownership entails. To this pleasure, camping gives a fine refinement. From one''s own front door to the hills or the sands and home again, everything is at hand. Not only are the means of reaching the holiday paradise within one''s own keeping, but the means of escaping a holiday that has soured — a beach too crowded, a sky too gray — are parked outside the tent, or are part of it. Idealists object that the camper, like the package tourist, denies himself the chance of getting to know the country he visits. Yet the charge does not survive a visit to a busy Continental site. Holiday hotels tend to cater to one nationality, sometimes to one alone; campsites, by contrast, are strongly cosmopolitan. Notices forbidding the drying of clothes in the open, or inviting ''our camping friends'' to a dance, are printed in French, German, and English alike. Whether the remarkable growth of organized camping means the slow death of the freer, more independent kind is hard to say. In the end it will depend on the campers themselves — on how many fires they start, how much litter they leave, and whether they wholly alienate the people of the countryside.","explanation_cn":"课文说:理想主义者指责露营者见不到当地人,但一到热闹的欧陆营地便站不住脚,因为营地高度国际化。✓ cosmopolitan sites."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',10,NULL,'choice','{"stem":"In the end, on what will the survival of freer, independent camping mainly depend?","options":["On the price of gasoline each year","On the number of hotels that close down","On the weather in the mountains","On the campers themselves — how many fires they start, how much litter they leave, and whether they alienate the countryside"],"answer_index":3,"audio":"Saving money is one powerful reason for camping. Once you have paid for your gear, or arranged to rent it, the total cost can be far less than a run of hotel bills. But, contrary to a common assumption, thrift is far from being the only reason, or even the greatest. The traveler who steers carelessly into his small paid square at one of Europe''s countless permanent sites may well find himself parked beside a gleaming sedan; more often a modest hatchback stands door to door with something far grander. That the gear of modern camping grows more elaborate every year is an amusing paradox for the cynic, and a brighter promise for the hopeful traveler who has sworn to get away from it all. It also offers — and some student of sociology might build a thesis on the fact — an escape of a different kind. The modern traveler is often a man who dislikes the grand hotel, not because he cannot afford its comforts or wishes to shun them, but because he is a little afraid of it. Affluent he may be, yet he is by no means sure what to tip the doorman or the maid. Master in his own house, he has small idea of when to complain to a headwaiter. From all such fears camping sets him free. A snobbery of camping does exist, based on gear and technique; but it is a kind that, should he meet it, he can readily understand and handle. There is no superior ''they'', no management and no hotel hierarchy, to darken his holiday. To these motives another must be added. The modern worship of the car is explained, not least, by the sense of independence that ownership entails. To this pleasure, camping gives a fine refinement. From one''s own front door to the hills or the sands and home again, everything is at hand. Not only are the means of reaching the holiday paradise within one''s own keeping, but the means of escaping a holiday that has soured — a beach too crowded, a sky too gray — are parked outside the tent, or are part of it. Idealists object that the camper, like the package tourist, denies himself the chance of getting to know the country he visits. Yet the charge does not survive a visit to a busy Continental site. Holiday hotels tend to cater to one nationality, sometimes to one alone; campsites, by contrast, are strongly cosmopolitan. Notices forbidding the drying of clothes in the open, or inviting ''our camping friends'' to a dance, are printed in French, German, and English alike. Whether the remarkable growth of organized camping means the slow death of the freer, more independent kind is hard to say. In the end it will depend on the campers themselves — on how many fires they start, how much litter they leave, and whether they wholly alienate the people of the countryside.","explanation_cn":"课文说:自由独立露营能否存续,最终取决于露营者自己——放多少火、留多少垃圾、是否得罪乡间的人。✓ depends on campers."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l47',10,NULL,'choice','{"stem":"Why does the writer call the growing sophistication of camping gear a paradox for the cynic?","options":["Because cynics never go camping at all","Because camping gear keeps getting cheaper","Because people take up camping to get away from it all, yet their equipment grows more elaborate every year","Because no one buys camping gear anymore"],"answer_index":2,"audio":"Saving money is one powerful reason for camping. Once you have paid for your gear, or arranged to rent it, the total cost can be far less than a run of hotel bills. But, contrary to a common assumption, thrift is far from being the only reason, or even the greatest. The traveler who steers carelessly into his small paid square at one of Europe''s countless permanent sites may well find himself parked beside a gleaming sedan; more often a modest hatchback stands door to door with something far grander. That the gear of modern camping grows more elaborate every year is an amusing paradox for the cynic, and a brighter promise for the hopeful traveler who has sworn to get away from it all. It also offers — and some student of sociology might build a thesis on the fact — an escape of a different kind. The modern traveler is often a man who dislikes the grand hotel, not because he cannot afford its comforts or wishes to shun them, but because he is a little afraid of it. Affluent he may be, yet he is by no means sure what to tip the doorman or the maid. Master in his own house, he has small idea of when to complain to a headwaiter. From all such fears camping sets him free. A snobbery of camping does exist, based on gear and technique; but it is a kind that, should he meet it, he can readily understand and handle. There is no superior ''they'', no management and no hotel hierarchy, to darken his holiday. To these motives another must be added. The modern worship of the car is explained, not least, by the sense of independence that ownership entails. To this pleasure, camping gives a fine refinement. From one''s own front door to the hills or the sands and home again, everything is at hand. Not only are the means of reaching the holiday paradise within one''s own keeping, but the means of escaping a holiday that has soured — a beach too crowded, a sky too gray — are parked outside the tent, or are part of it. Idealists object that the camper, like the package tourist, denies himself the chance of getting to know the country he visits. Yet the charge does not survive a visit to a busy Continental site. Holiday hotels tend to cater to one nationality, sometimes to one alone; campsites, by contrast, are strongly cosmopolitan. Notices forbidding the drying of clothes in the open, or inviting ''our camping friends'' to a dance, are printed in French, German, and English alike. Whether the remarkable growth of organized camping means the slow death of the freer, more independent kind is hard to say. In the end it will depend on the campers themselves — on how many fires they start, how much litter they leave, and whether they wholly alienate the people of the countryside.","explanation_cn":"课文说:人们露营本为摆脱一切,装备却一年比一年讲究,对愤世嫉俗者这就是个悖论。✓ paradox of gear."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l48',4,8,48,'Planning a Share Portfolio','规划股份投资','真实条件句 if(if + 一般现在时, 主句一般现在/将来)、even if 让步状语从句、be likely to do(很可能…)、there is no shortage of + 名词/动名词(不乏…)、不定式作定语(money to fritter / time to recover)(NCE4 该课源无独立 KS 页,考点由课文结构自取;IP:源为《Investor''s Chronicle》一段谈‘如何规划投资组合’的理财随笔,系版权作品——已用 100% 原创行文复述其观点、无引用原句;词表按 CONSTITUTION 第0章取现代可教的12个理财词,舍弃 tipster/gilt/convertible/sanguine/heady/pedestrian 等生僻词、并补足课文动词 boost/preserve/generate/spread;题材=个人理财·无害;美语化 check/favor/organize;★第四册第48课·全书最后一课)','不乏有人向你许诺一夜暴富。但如果你是个认真的私人投资者,就把那种赌场心态留给有闲钱可挥霍的人吧。认真的投资者需要一份像样的投资组合——一套精心规划、结构分明、目标清晰的投资安排。可是,一个股市新手究竟该怎样着手去建立它呢?其实,你若去问五位有声望的经纪人该拿积蓄怎么办,很可能会得到五个不同的答案——哪怕你把年龄、家庭、财务状况以及你想让钱达成什么,统统如实相告。这说明什么?没有唯一‘正确’的方法来构建投资组合;然而,错误的方法却有的是,而且可以肯定,那五位顾问中没有一个人会劝你把每一块钱都砸进一家小公司。那么你该怎么做?我们假定你已把基础都理顺了——一笔你负担得起的按揭、一份养老金、保险,以及留有足够的现金储备。接着,你要确立自己的目标。这些目标一半取决于你的处境,一半取决于你的性情。比如说,你若年纪大些,从重大亏损中恢复的时间就少一些,你很可能想提高退休后的收入。这种情形下,保住本金、稳稳地生出一份额外收入,就成了你的首要任务;于是你会搭一个稳健的组合——挑稳妥的股票而非高风险的,再配上安全的债券和现金存款。你若年轻些、财务根基又扎实,或许会选一种更大胆的路子——但前提是你有那份胆量,不会为当天的股价而彻夜难眠。到那时,也只有到那时,你才可以在稳当的持仓之外,搭上几只快速成长的股票。即便市场回落,你也还有往后的岁月把损失赚回来。一旦目标定下,你就能决定把钱投向何处。这里的黄金法则很简单:分散你的风险。你若把一切都倒进一家公司——不管它今天看起来多有前途——你就把自己变成了任凭命运摆布的人质。分散投资,盯住目标,让投资组合、而不是那些荐股的人,去替你做功。','{"q":"Listen and answer — How does the older investor''s approach to investment differ from the younger investor''s?","options":["The older investor preserves capital and seeks income, having less time to recover, while the younger one can afford a bolder, riskier approach","The older investor takes far more risks than the younger one","Both invest in exactly the same way","Neither of them plans a portfolio at all"],"answer_index":0}'::jsonb,'{"title":"真实条件句 if / even if 让步状语从句 / be likely to do / there is no shortage of + 动名词 / 不定式作定语","intro":"①真实条件句:if 从句用一般现在时,主句用一般现在时(表真理/习惯)或一般将来时(will)。②even if:‘即使…(也)’,引导让步,所设情况往往是假设的。③be likely to do:‘很可能…’,likely 后接不定式。④there is no shortage of + 名词/动名词:‘不乏…,有的是…’。⑤不定式作定语:名词 + to do,表‘用来…的、该…的’(money to fritter、time to recover)。","table":{"headers":["用法","结构","例子"],"rows":[["真实条件句 if","if + 一般现在时, 一般现在/将来","If you are older, you have less time"],["even if 让步","even if + 从句","Even if prices fall, you can wait"],["be likely to do","be likely + to do","you are likely to get five answers"],["there is no shortage of","there is no shortage of + 名词/动名词","There is no shortage of tipsters offering tips"],["不定式作定语","名词 + to do","money to fritter; time to recover"]]},"specialRules":[{"rule":"真实条件句里,if 从句不用 will:If you are older(不是 If you will be older);表将来的 will 放在主句。","mark":"if + 一般现在时"},{"rule":"even if(即使,多为假设)不同于 even though(尽管,是事实):设想尚未发生的情况用 even if。","mark":"even if / even though"},{"rule":"美式拼写:check(支票)/ favor / organize(英式 cheque / favour / organise)。本课已按美语写。","mark":"check / organize"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l48',1,NULL,'There is no shortage of tipsters offering to make you rich overnight. But if you are a serious private investor, leave that casino spirit to people with money to fritter away. The serious investor needs a proper portfolio — a carefully planned set of investments, with a definite structure and a clear aim. Yet how exactly does a newcomer to the stock market set about building one?','不乏有人向你许诺一夜暴富。但如果你是个认真的私人投资者,就把那种赌场心态留给有闲钱可挥霍的人吧。认真的投资者需要一份像样的投资组合——一套精心规划、结构分明、目标清晰的投资安排。可是,一个股市新手究竟该怎样着手去建立它呢?') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l48',2,NULL,'Well, if you ask five reputable brokers what you ought to do with your savings, you are likely to get five different answers — even if you give them every relevant fact about your age, your family, your finances, and what you want your money to do. The moral? There is no single right way to build a portfolio. There are, however, plenty of wrong ways, and you can be sure that none of those five advisers would have told you to sink every dollar into one small company.','其实,你若去问五位有声望的经纪人该拿积蓄怎么办,很可能会得到五个不同的答案——哪怕你把年龄、家庭、财务状况以及你想让钱达成什么,统统如实相告。这说明什么?没有唯一‘正确’的方法来构建投资组合;然而,错误的方法却有的是,而且可以肯定,那五位顾问中没有一个人会劝你把每一块钱都砸进一家小公司。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l48',3,NULL,'So what should you do? We will assume you have already sorted out the basics — a mortgage you can manage, a pension, insurance, and enough cash held in reserve. You should then set your own aims. These depend partly on your circumstances and partly on your temperament.','那么你该怎么做?我们假定你已把基础都理顺了——一笔你负担得起的按揭、一份养老金、保险,以及留有足够的现金储备。接着,你要确立自己的目标。这些目标一半取决于你的处境,一半取决于你的性情。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l48',4,NULL,'If you are older, for instance, you have less time to recover from any serious loss, and you may well want to boost your retirement income. In that case, preserving your capital and generating a steady extra income become your first priorities, and you would build a cautious portfolio — sound shares rather than risky ones, together with safe bonds and cash deposits.','比如说,你若年纪大些,从重大亏损中恢复的时间就少一些,你很可能想提高退休后的收入。这种情形下,保住本金、稳稳地生出一份额外收入,就成了你的首要任务;于是你会搭一个稳健的组合——挑稳妥的股票而非高风险的,再配上安全的债券和现金存款。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l48',5,NULL,'If you are younger, and on solid financial ground, you may choose a bolder approach — but only if you have the nerve for it and will not lie awake over the day''s share prices. Even if the market dips, you have the years ahead to make the loss back. Once your aims are settled, the golden rule is simple: spread your risk. If you pour everything into a single company, however promising it looks today, you are setting yourself up as a hostage to fortune.','你若年轻些、财务根基又扎实,或许会选一种更大胆的路子——但前提是你有那份胆量,不会为当天的股价而彻夜难眠。即便市场回落,你也还有往后的岁月把损失赚回来。一旦目标定下,黄金法则很简单:分散你的风险。你若把一切都倒进一家公司——不管它今天看起来多有前途——你就把自己变成了任凭命运摆布的人质。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
