INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l48','set about','',NULL,'/set əˈbaʊt/','How does a newcomer set about building a portfolio?','新手该怎样着手构建投资组合?','She set about cleaning the whole house.','她开始动手打扫整所房子。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l48','spread your risk','',NULL,'/spred jʊr rɪsk/','The golden rule is simple: spread your risk.','黄金法则很简单:分散你的风险。','Buy several stocks to spread your risk.','买几只股票来分散你的风险。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l48','a hostage to fortune','',NULL,'/ə ˈhɑːstɪdʒ tə ˈfɔːrtʃən/','Put all in one firm and you are a hostage to fortune.','全押一家公司,你就任凭命运摆布。','Such a rash promise made him a hostage to fortune.','如此草率的承诺让他陷入听天由命的境地。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l48','lie awake','',NULL,'/laɪ əˈweɪk/','A bold investor will not lie awake over share prices.','大胆的投资者不会为股价彻夜难眠。','He lay awake worrying about the exam.','他躺着睡不着,为考试发愁。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp1','choice','{"stem":"\"If you ___ older, you have less time to recover from a loss.\"(真实条件句,if 从句用一般现在时,填 be 动词的现在式)","options":["were","are","will be","would be"],"answer_index":1,"stem_cn":"如果你年纪大些,你恢复损失的时间就少一些。","explanation_cn":"真实条件句:if 从句用一般现在时,主语 you 配 are。✓ If you are older, you have less time. ✗ were(与现在相反的虚拟)/ will be(if 从句不用 will)/ would be:真实条件用现在时 are。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp1','choice','{"stem":"\"If the market dips next year, you ___ still have time to recover.\"(真实条件句,主句表将来,填将来时的助动词)","options":["will","are","did","would"],"answer_index":0,"stem_cn":"如果市场明年回落,你仍会有时间恢复。","explanation_cn":"真实条件句主句表将来,用 will + 动词原形;填 will。✓ you will still have time to recover. ✗ would(虚拟)/ are / did:主句表将来用 will。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp1','choice','{"stem":"\"If you ___ your risk, you protect yourself against a single failure.\"(真实条件句,if 从句一般现在时,主语 you,填动词原形)","options":["spreads","spread","spreading","will spread"],"answer_index":1,"stem_cn":"如果你分散风险,就能保护自己免受单笔失败之害。","explanation_cn":"真实条件句 if 从句用一般现在时,主语 you 用动词原形 spread。✓ If you spread your risk, you protect yourself. ✗ spreads(用于第三人称单数)/ will spread(if 从句不用 will)/ spreading。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp2','choice','{"stem":"\"___ if you give every fact, you may still get five different answers.\"(‘即使…’引导让步,填与 if 连用表‘即使’的那个词)","options":["Only","So","As","Even"],"answer_index":3,"stem_cn":"即使你提供每一个事实,仍可能得到五个不同的答案。","explanation_cn":"‘即使…’引导让步,与 if 连用作 even if;填 Even。✓ Even if you give every fact… ✗ As / So / Only:表‘即使’与 if 搭配的是 Even。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp2','choice','{"stem":"\"Even ___ the market dips next year, a young investor can wait.\"(表‘即使’的让步结构,填 even 之后那个词)","options":["so","for","if","though"],"answer_index":2,"stem_cn":"即使市场明年回落,年轻的投资者也等得起。","explanation_cn":"even ___ 表‘即使(假设)’= even if;填 if。✓ Even if the market dips next year… ✗ though(even though 表‘尽管’,是事实,与‘明年回落’这一假设不符)/ for / so。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp2','choice','{"stem":"\"Even ___ share prices fall tomorrow, you have years ahead.\"(表‘即使’、所设情况尚未发生,填 even 之后那个词)","options":["though","if","that","when"],"answer_index":1,"stem_cn":"即使股价明天下跌,你还有往后的岁月。","explanation_cn":"even ___ 表‘即使(尚未发生)’= even if;填 if。✓ Even if share prices fall tomorrow… ✗ though(表事实)/ when(表时间)/ that:设想未发生的情况用 even if。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp3','choice','{"stem":"\"Ask five brokers and you are ___ to get five different answers.\"(‘很可能…’的固定说法 be ___ to do,填 be 与 to 之间那个形容词)","options":["likely","alike","likable","like"],"answer_index":0,"stem_cn":"问五个经纪人,你很可能得到五个不同的答案。","explanation_cn":"‘很可能…’= be likely to do;be 之后接形容词 likely。✓ you are likely to get five answers. ✗ like(像)/ alike(相像的)/ likable(讨人喜欢的):此处是 be likely to。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp3','choice','{"stem":"\"A cautious investor is likely ___ preserve his capital first.\"(be likely + 不定式,填不定式符号)","options":["of","for","to","that"],"answer_index":2,"stem_cn":"谨慎的投资者很可能会先保住本金。","explanation_cn":"be likely 后接不定式;填不定式符号 to。✓ is likely to preserve his capital first. ✗ for / of / that:likely 后接 to + 动词原形。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp3','choice','{"stem":"\"Without a plan, you are likely to ___ your money away.\"(be likely to + 动词原形,填‘挥霍’那个动词原形)","options":["fritter","frittering","to fritter","frittered"],"answer_index":0,"stem_cn":"没有计划,你很可能把钱一点点挥霍掉。","explanation_cn":"be likely to 后接动词原形;填‘挥霍’的原形 fritter。✓ likely to fritter your money away. ✗ frittered / frittering / to fritter:to 之后已是不定式,再接原形 fritter。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp4','choice','{"stem":"\"There is no ___ of tipsters offering quick riches.\"(‘不乏…,有的是…’的固定说法 there is no ___ of,填 no 与 of 之间那个名词)","options":["shorten","shortage","short","shortness"],"answer_index":1,"stem_cn":"不乏许诺快速致富的荐股人。","explanation_cn":"‘不乏…,有的是…’= there is no shortage of;填名词 shortage。✓ there is no shortage of tipsters. ✗ short(形容词)/ shorten(动词)/ shortness(状态):固定短语用 shortage。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp4','choice','{"stem":"\"There is no shortage of advisers ___ you get-rich-quick tips.\"(there is no shortage of + 名词 + 现在分词,填 offer 的 -ing 形式)","options":["offered","to offer","offering","offer"],"answer_index":2,"stem_cn":"不乏向你抛出快速致富建议的顾问。","explanation_cn":"there is no shortage of + 名词 + 现在分词作定语;填 offer 的 -ing 形式 offering。✓ advisers offering you tips. ✗ offer / offered / to offer:主动的后置修饰用现在分词。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp4','choice','{"stem":"\"There ___ no shortage of wrong ways to build a portfolio.\"(there be 句型,shortage 为单数主语,填 be 动词)","options":["be","is","being","are"],"answer_index":1,"stem_cn":"构建投资组合的错误方法有的是。","explanation_cn":"there be 句型,主语 shortage 为单数,用 is。✓ There is no shortage of wrong ways. ✗ are(主语单数不用 are)/ be / being。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp5','choice','{"stem":"\"Leave that casino spirit to people with money ___ fritter away.\"(不定式作定语修饰 money,填不定式符号)","options":["for","of","with","to"],"answer_index":3,"stem_cn":"把那种赌场心态留给有闲钱可挥霍的人。","explanation_cn":"不定式作定语,修饰 money,‘可挥霍的钱’;填不定式符号 to。✓ money to fritter away. ✗ for / of / with:名词后的不定式定语用 to + 动词原形。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp5','choice','{"stem":"\"He kept some cash ___ when prices fell.\"(不定式作定语‘可用来投资的现金’,填 invest 的正确形式)","options":["investing","to invest","invested","invest"],"answer_index":1,"stem_cn":"他留了些现金,以便在价格下跌时投入。","explanation_cn":"不定式作定语,修饰 cash,‘可用来投资的现金’;填 to + 动词原形 to invest。✓ some cash to invest when prices fell. ✗ investing / invested / invest:名词后的不定式定语用 to invest。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp5','choice','{"stem":"\"There was little money ___ on luxuries.\"(不定式作定语‘可花在…的钱’,填 spend 的不定式形式)","options":["spent","spend","spending","to spend"],"answer_index":3,"stem_cn":"没有多少钱可花在奢侈品上。","explanation_cn":"不定式作定语,修饰 money,‘可花的钱’;填 to + 动词原形 to spend。✓ little money to spend on luxuries. ✗ spending / spent / spend:名词后的不定式定语用 to spend。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp6','choice','{"stem":"\"A carefully planned set of investments is called a ___.\"(“投资组合”用哪个词)","options":["platform","portfolio","porcelain","platoon"],"answer_index":1,"stem_cn":"一套精心规划的投资安排。","explanation_cn":"一套精心规划的投资安排叫 portfolio(投资组合)。✓ a proper portfolio. ✗ platform 平台;✗ platoon 排(军事);✗ porcelain 瓷器——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp6','choice','{"stem":"\"To keep something safe and unchanged is to ___ it.\"(“保护,保全”用哪个词)","options":["preserve","preview","presume","prescribe"],"answer_index":0,"stem_cn":"使某物安全、不受损失。","explanation_cn":"使某物安全、不受损失是 preserve(保护、保全)。✓ preserving your capital. ✗ preview 预览;✗ presume 假定;✗ prescribe 开处方——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',5,'am4_l48_gp6','choice','{"stem":"\"To waste money little by little on trifles is to ___ it away.\"(“挥霍,浪费”用哪个词)","options":["flatter","flutter","filter","fritter"],"answer_index":3,"stem_cn":"把钱一点点浪费在琐碎小事上。","explanation_cn":"把钱一点点浪费在琐事上是 fritter(挥霍、浪费)。✓ money to fritter away. ✗ flatter 奉承;✗ flutter 飘动;✗ filter 过滤——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',6,NULL,'choice','{"stem":"portfolio 的意思是:","options":["银行罚息","交易佣金","单一股票","投资组合"],"answer_index":3,"explanation_cn":"portfolio = 投资组合。✓ the investor needs a proper portfolio."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',6,NULL,'choice','{"stem":"broker 的意思是:","options":["经纪人,中间商","债务人","银行家","会计师"],"answer_index":0,"explanation_cn":"broker = 经纪人、中间商。✓ five reputable brokers."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',6,NULL,'choice','{"stem":"mortgage 的意思是:","options":["保险单","抵押贷款,按揭","养老金","红利"],"answer_index":1,"explanation_cn":"mortgage = 抵押贷款、按揭。✓ a mortgage you can manage."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',6,NULL,'choice','{"stem":"pension 的意思是:","options":["佣金","罚款","养老金","押金"],"answer_index":2,"explanation_cn":"pension = 养老金。✓ a pension, insurance, and cash reserves."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',6,NULL,'choice','{"stem":"preserve 的意思是:","options":["抵押,担保","保护,保全","挥霍,浪费","分散,分开"],"answer_index":1,"explanation_cn":"preserve = 保护、保全。✓ preserving your capital."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',6,NULL,'choice','{"stem":"generate 的意思是:","options":["产生,带来","偿还,归还","冻结,锁定","消耗,花掉"],"answer_index":0,"explanation_cn":"generate = 产生、带来。✓ generating a steady extra income."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',7,NULL,'cloze','{"stem":"第 1 空","context":"There is no ___1___ of tipsters promising quick riches, but a serious investor needs a real plan. If you ___2___ older, you have less time to recover, so you protect your capital. If you are young, you can take more risk — even ___3___ prices fall, you have years ahead. Ask five brokers and you are ___4___ to get five answers.","blank_no":1,"options":["shortage","short","shorten","shortness"],"answer_index":0,"explanation_cn":"‘不乏…’= there is no shortage of;填 shortage。✓ there is no shortage of tipsters."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',7,NULL,'cloze','{"stem":"第 2 空","context":"There is no ___1___ of tipsters promising quick riches, but a serious investor needs a real plan. If you ___2___ older, you have less time to recover, so you protect your capital. If you are young, you can take more risk — even ___3___ prices fall, you have years ahead. Ask five brokers and you are ___4___ to get five answers.","blank_no":2,"options":["are","were","will be","would be"],"answer_index":0,"explanation_cn":"真实条件句 if 从句用一般现在时;主语 you 配 are。✓ If you are older, you have less time."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',7,NULL,'cloze','{"stem":"第 3 空","context":"There is no ___1___ of tipsters promising quick riches, but a serious investor needs a real plan. If you ___2___ older, you have less time to recover, so you protect your capital. If you are young, you can take more risk — even ___3___ prices fall, you have years ahead. Ask five brokers and you are ___4___ to get five answers.","blank_no":3,"options":["if","though","when","that"],"answer_index":0,"explanation_cn":"even ___ 表‘即使(假设)’= even if;填 if。✓ even if prices fall, you have years ahead."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',7,NULL,'cloze','{"stem":"第 4 空","context":"There is no ___1___ of tipsters promising quick riches, but a serious investor needs a real plan. If you ___2___ older, you have less time to recover, so you protect your capital. If you are young, you can take more risk — even ___3___ prices fall, you have years ahead. Ask five brokers and you are ___4___ to get five answers.","blank_no":4,"options":["likely","like","alike","likable"],"answer_index":0,"explanation_cn":"‘很可能…’= be likely to do;填 likely。✓ you are likely to get five answers."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',8,NULL,'choice','{"stem":"How does the older investor''s approach differ from the younger investor''s?","options":["They both refuse to plan at all","The younger investor only ever buys safe bonds","The older investor always takes the bigger risks","The older investor preserves capital and seeks income, since he has less time to recover; the younger one can afford a bolder, riskier approach"],"answer_index":3,"explanation_cn":"录音说:年长者时间有限,重在保本、求收入;年轻者根基稳,可采取更大胆、风险更高的路子。✓ older preserves, younger bolder."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',8,NULL,'choice','{"stem":"What is the ''golden rule'' the writer gives for deciding where to put your money?","options":["Keep every dollar in cash and never invest","Put all your money into the most promising company","Spread your risk — never pour everything into a single company","Always follow the first tipster you meet"],"answer_index":2,"explanation_cn":"录音说:黄金法则是分散风险,绝不把一切押进一家公司。✓ spread your risk."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',8,NULL,'choice','{"stem":"Why are you likely to get five different answers if you ask five brokers?","options":["Because there is only one correct answer they all hide","Because there is no single right way to build a portfolio, though there are plenty of wrong ways","Because brokers are not allowed to agree","Because they never listen to your circumstances"],"answer_index":1,"explanation_cn":"录音说:五个经纪人给五个答案,因为构建组合没有唯一正解,错误的做法倒有的是。✓ no single right way."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',9,NULL,'choice','{"stem":"你想说\"如果你年纪大些,你恢复损失的时间就少一些\"(真实条件句 if):","options":["If you are older, you had less time to recover from a loss.","If you are older, you have less time to recover from a loss.","If you will be older, you have less time to recover from a loss.","If you were older, you have less time to recover from a loss."],"answer_index":1,"explanation_cn":"说事实/一般规律时,if 那半句用 are、后半句用 have,前后都用一般现在时;if 那半句不用 will be,也不用与现在相反的 were,后半句别改成过去的 had。✓ If you are older, you have… 场合:说“如果……(一般情况),就……”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',9,NULL,'choice','{"stem":"你想说\"即使你提供了每一个事实,你仍可能得到五个不同的答案\"(even if 让步):","options":["If even you give every fact, you may still get five different answers.","Even you give every fact, you may still get five different answers.","Even though you give every fact, you may still get five different answers.","Even if you give every fact, you may still get five different answers."],"answer_index":3,"explanation_cn":"表“即使(假设也)”要用 Even if(不用表“尽管、事实如此”的 Even though);Even 后要带 if,不能只写 Even,也不能写成 If even。✓ Even if you give… 场合:说“即使……,也……”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',9,NULL,'choice','{"stem":"你想说\"问五个经纪人,你很可能得到五个不同的答案\"(be likely to do):","options":["Ask five brokers, and you are likely to get five different answers.","Ask five brokers, and you are like to get five different answers.","Ask five brokers, and you are likely get five different answers.","Ask five brokers, and you likely to get five different answers."],"answer_index":0,"explanation_cn":"“很可能……”要用 are likely to get:likely 前有 are、后接 to,再接动词;不能漏 to(likely get)、不能写成 like、也不能漏 are。✓ you are likely to get… 场合:说“很可能会……”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',10,NULL,'choice','{"stem":"preserve 的意思是:","options":["挥霍,浪费","出售,变卖","保护,保全","借入,借出"],"answer_index":2,"explanation_cn":"preserve = 保护、保全。✓ preserving your capital."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',10,NULL,'choice','{"stem":"portfolio 的意思是:","options":["投资组合","交易佣金","银行罚息","单一股票"],"answer_index":0,"explanation_cn":"portfolio = 投资组合。✓ a proper portfolio."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',10,NULL,'choice','{"stem":"\"If you ___ older, you have less time to recover from a loss.\"(真实条件句,if 从句用一般现在时)","options":["were","will be","would be","are"],"answer_index":3,"stem_cn":"如果你年纪大些,你恢复损失的时间就少一些。","explanation_cn":"真实条件句 if 从句用一般现在时;主语 you 配 are。✓ If you are older, you have less time. ✗ were / will be / would be。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',10,NULL,'choice','{"stem":"\"___ if you give every fact, you may still get five answers.\"(‘即使…’引导让步)","options":["Even","So","Only","As"],"answer_index":0,"stem_cn":"即使你提供每一个事实,仍可能得到五个答案。","explanation_cn":"‘即使…’引导让步,与 if 连用作 even if;填 Even。✓ Even if you give every fact. ✗ As / So / Only。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',10,NULL,'choice','{"stem":"\"spread your risk\" 的意思是:","options":["放弃全部投资","增加投资金额","分散投资以降低风险","隐瞒你的损失"],"answer_index":2,"explanation_cn":"spread your risk = 分散投资以降低风险。✓ the golden rule: spread your risk."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',10,NULL,'choice','{"stem":"\"a hostage to fortune\" 的意思是:","options":["把命运押在运气上、听天由命的处境","一位可靠的顾问","一份稳妥的保险","一笔巨大的财富"],"answer_index":0,"explanation_cn":"a hostage to fortune = 把命运押在运气上、听天由命的处境。✓ you are setting yourself up as a hostage to fortune."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',10,NULL,'choice','{"stem":"Why does the writer say an older investor should preserve capital and seek income?","options":["Because income is illegal for younger investors","Because older people are not allowed to buy shares","Because he has less time to recover from a serious loss and may want to boost his retirement income","Because he enjoys taking big risks"],"answer_index":2,"passage":"There is no shortage of tipsters offering to make you rich overnight. But if you are a serious private investor, leave that casino spirit to people with money to fritter away. The serious investor needs a proper portfolio — a carefully planned set of investments, with a definite structure and a clear aim. Yet how exactly does a newcomer to the stock market set about building one? Well, if you ask five reputable brokers what you ought to do with your savings, you are likely to get five different answers — even if you give them every relevant fact about your age, your family, your finances, and what you want your money to do. The moral? There is no single right way to build a portfolio. There are, however, plenty of wrong ways, and you can be sure that none of those five advisers would have told you to sink every dollar into one small company. So what should you do? We will assume you have already sorted out the basics — a mortgage you can manage, a pension, insurance, and enough cash held in reserve. You should then set your own aims. These depend partly on your circumstances and partly on your temperament. If you are older, for instance, you have less time to recover from any serious loss, and you may well want to boost your retirement income. In that case, preserving your capital and generating a steady extra income become your first priorities, and you would build a cautious portfolio — sound shares rather than risky ones, together with safe bonds and cash deposits. If you are younger, and on solid financial ground, you may choose a bolder approach — but only if you have the nerve for it and will not lie awake over the day''s share prices. Then, and only then, you might place a few fast-growing stocks alongside your steadier holdings. Even if the market dips, you have the years ahead to make the loss back. Once your aims are settled, you can decide where to put your money. The golden rule here is simple: spread your risk. If you pour everything into a single company, however promising it looks today, you are setting yourself up as a hostage to fortune. Diversify, keep your aim in view, and let the portfolio — not the tipster — do the work.","explanation_cn":"课文说:年长者应保本求收入,因为从重大亏损中恢复的时间较少,且往往想提高退休收入。✓ less time to recover."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',10,NULL,'choice','{"stem":"Under what condition does the writer say a younger investor may take a bolder approach?","options":["Only if he borrows money from five brokers","Only after he has retired","Only if he puts everything into one company","Only if he has the nerve for it and will not lie awake worrying over the day''s share prices"],"answer_index":3,"passage":"There is no shortage of tipsters offering to make you rich overnight. But if you are a serious private investor, leave that casino spirit to people with money to fritter away. The serious investor needs a proper portfolio — a carefully planned set of investments, with a definite structure and a clear aim. Yet how exactly does a newcomer to the stock market set about building one? Well, if you ask five reputable brokers what you ought to do with your savings, you are likely to get five different answers — even if you give them every relevant fact about your age, your family, your finances, and what you want your money to do. The moral? There is no single right way to build a portfolio. There are, however, plenty of wrong ways, and you can be sure that none of those five advisers would have told you to sink every dollar into one small company. So what should you do? We will assume you have already sorted out the basics — a mortgage you can manage, a pension, insurance, and enough cash held in reserve. You should then set your own aims. These depend partly on your circumstances and partly on your temperament. If you are older, for instance, you have less time to recover from any serious loss, and you may well want to boost your retirement income. In that case, preserving your capital and generating a steady extra income become your first priorities, and you would build a cautious portfolio — sound shares rather than risky ones, together with safe bonds and cash deposits. If you are younger, and on solid financial ground, you may choose a bolder approach — but only if you have the nerve for it and will not lie awake over the day''s share prices. Then, and only then, you might place a few fast-growing stocks alongside your steadier holdings. Even if the market dips, you have the years ahead to make the loss back. Once your aims are settled, you can decide where to put your money. The golden rule here is simple: spread your risk. If you pour everything into a single company, however promising it looks today, you are setting yourself up as a hostage to fortune. Diversify, keep your aim in view, and let the portfolio — not the tipster — do the work.","explanation_cn":"课文说:年轻投资者只有在有胆量、且不会为当天股价失眠的前提下,才可采取更大胆的路子。✓ only if he has the nerve."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',10,NULL,'choice','{"stem":"What is the single ''golden rule'' the writer gives about where to put your money?","options":["Spread your risk, and never pour everything into one company","Keep all your money under the bed","Trust the first tipster you meet","Buy only one company''s shares"],"answer_index":0,"audio":"There is no shortage of tipsters offering to make you rich overnight. But if you are a serious private investor, leave that casino spirit to people with money to fritter away. The serious investor needs a proper portfolio — a carefully planned set of investments, with a definite structure and a clear aim. Yet how exactly does a newcomer to the stock market set about building one? Well, if you ask five reputable brokers what you ought to do with your savings, you are likely to get five different answers — even if you give them every relevant fact about your age, your family, your finances, and what you want your money to do. The moral? There is no single right way to build a portfolio. There are, however, plenty of wrong ways, and you can be sure that none of those five advisers would have told you to sink every dollar into one small company. So what should you do? We will assume you have already sorted out the basics — a mortgage you can manage, a pension, insurance, and enough cash held in reserve. You should then set your own aims. These depend partly on your circumstances and partly on your temperament. If you are older, for instance, you have less time to recover from any serious loss, and you may well want to boost your retirement income. In that case, preserving your capital and generating a steady extra income become your first priorities, and you would build a cautious portfolio — sound shares rather than risky ones, together with safe bonds and cash deposits. If you are younger, and on solid financial ground, you may choose a bolder approach — but only if you have the nerve for it and will not lie awake over the day''s share prices. Then, and only then, you might place a few fast-growing stocks alongside your steadier holdings. Even if the market dips, you have the years ahead to make the loss back. Once your aims are settled, you can decide where to put your money. The golden rule here is simple: spread your risk. If you pour everything into a single company, however promising it looks today, you are setting yourself up as a hostage to fortune. Diversify, keep your aim in view, and let the portfolio — not the tipster — do the work.","explanation_cn":"课文说:关于把钱投向何处,唯一的黄金法则就是分散风险,绝不把一切倒进一家公司。✓ spread your risk."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l48',10,NULL,'choice','{"stem":"According to the writer, why will you get five different answers from five reputable brokers?","options":["Because brokers never tell the truth","Because only one of them knows anything","Because there is no single right way to build a portfolio, even if you give them every relevant fact","Because they refuse to hear your details"],"answer_index":2,"audio":"There is no shortage of tipsters offering to make you rich overnight. But if you are a serious private investor, leave that casino spirit to people with money to fritter away. The serious investor needs a proper portfolio — a carefully planned set of investments, with a definite structure and a clear aim. Yet how exactly does a newcomer to the stock market set about building one? Well, if you ask five reputable brokers what you ought to do with your savings, you are likely to get five different answers — even if you give them every relevant fact about your age, your family, your finances, and what you want your money to do. The moral? There is no single right way to build a portfolio. There are, however, plenty of wrong ways, and you can be sure that none of those five advisers would have told you to sink every dollar into one small company. So what should you do? We will assume you have already sorted out the basics — a mortgage you can manage, a pension, insurance, and enough cash held in reserve. You should then set your own aims. These depend partly on your circumstances and partly on your temperament. If you are older, for instance, you have less time to recover from any serious loss, and you may well want to boost your retirement income. In that case, preserving your capital and generating a steady extra income become your first priorities, and you would build a cautious portfolio — sound shares rather than risky ones, together with safe bonds and cash deposits. If you are younger, and on solid financial ground, you may choose a bolder approach — but only if you have the nerve for it and will not lie awake over the day''s share prices. Then, and only then, you might place a few fast-growing stocks alongside your steadier holdings. Even if the market dips, you have the years ahead to make the loss back. Once your aims are settled, you can decide where to put your money. The golden rule here is simple: spread your risk. If you pour everything into a single company, however promising it looks today, you are setting yourself up as a hostage to fortune. Diversify, keep your aim in view, and let the portfolio — not the tipster — do the work.","explanation_cn":"课文说:即便你把每个相关事实都告诉五位有声望的经纪人,仍会得到五个答案,因为构建组合没有唯一正确的方法。✓ no single right way."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
